          '미국: 중국산 전자제품에 대한 통상법 301조 관세는 2026년에도 계속 유효합니다. 별도의 2025년 "IEEPA" 관세는 2026년 2월 대법원에 의해 무효화되었고, 기간 한정에 상한이 있는 통상법 122조 관세로 대체되었습니다. 직접 수입 800달러 미만에 적용되던 면세 "최소 기준(de minimis)" 예외도 종료되었습니다.',
